      mimeType: "text/html",
      fileName: "newsletter.html",
    },
  },
};

// n8n Function node
// Expects item.json with html_template + structured fields like:
// blog_title, blog_text, blog_cta_label, blog_url, ...
// Outputs the same JSON + html_rendered (final email HTML)

return items.map(item => {
  const data = item.json;

  const base = String(data.image_base_url || '').replace(/\/$/, '');

  // -----------------------------
  // Basic helpers
  // -----------------------------
  const t = (v) => (typeof v === 'string' ? v.trim() : (v ?? ''));

  const full = (v) => {
    const s = t(v);
    if (!s) return '';
    if (/^https?:\/\//i.test(s)) return s; // already absolute
    return base + s;
  };

  const normalizeText = (value) => {
    if (value == null) return '';
    return String(value)
      .replace(/\r\n/g, '\n')
      .replace(/\r/g, '\n')
      .trim();
  };

  const escapeHtml = (str) =>
    String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

  const escapeAttr = (str) =>
    String(str)
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

  // Plain text -> safe HTML for email text blocks
  // Rule: every newline becomes <br>
  // So:
  // 1 enter  -> <br>
  // 2 entery -> <br><br>
  // 3 entery -> <br><br><br>
  const formatPlainTextToEmailHtml = (rawText) => {
    const normalized = normalizeText(rawText);
    if (!normalized) return '';

    return escapeHtml(normalized)
      .replace(/\u00A0/g, '&nbsp;') // preserve real NBSP chars
      .replace(/\n/g, '<br>');
  };

  // Estimate text "visual lines" for spacer calculation
  // - counts explicit newlines
  // - counts wrapped lines by average chars per line
  const estimateVisualLines = (rawText, charsPerLine = 42) => {
    const normalized = normalizeText(rawText);
    if (!normalized) return 0;

    const paragraphs = normalized.split('\n');
    let lines = 0;

    for (const row of paragraphs) {
      const clean = row.replace(/\u00A0/g, ' ').replace(/\s+/g, ' ').trim();

      // Empty line still visually occupies a line break
      if (!clean) {
        lines += 1;
        continue;
      }

      lines += Math.max(1, Math.ceil(clean.length / charsPerLine));
    }

    return lines;
  };

  // Dynamic spacer for CTA alignment
  // Tune targetLines / lineHeightPx / maxSpacer for your design
  const getSpacerFromText = (rawText, options = {}) => {
    const {
      charsPerLine = 42,
      targetLines = 8,
      lineHeightPx = 20,
      maxSpacer = 80,
      minSpacer = 8,
    } = options;

    const lines = estimateVisualLines(rawText, charsPerLine);
    if (!rawText || !normalizeText(rawText)) return maxSpacer;

    const spacer = Math.max(0, targetLines - lines) * lineHeightPx;
    return Math.max(minSpacer, Math.min(maxSpacer, spacer));
  };

  // -----------------------------
  // Supabase image helpers
  // -----------------------------
  const supabaseCollectionBase =
    'https://izohjxqvhacjmutgnckf.supabase.co/storage/v1/object/public/Newsletter/collection_images/';
  const supabasePatternBase =
    'https://izohjxqvhacjmutgnckf.supabase.co/storage/v1/object/public/Newsletter/pattern_images/';

  const supabaseImg = (baseUrl, nameRaw) => {
    const name = t(nameRaw);
    if (!name) return '';
    return `${baseUrl}${name}.png`;
  };

  // -----------------------------
  // HTML template
  // -----------------------------
  let html = t(data.html_template);
  if (!html) {
    throw new Error('html_template is missing on item.json');
  }

  // -----------------------------
  // Token replacement helpers
  // -----------------------------
  const rep = (tokenRaw, value) => {
    const val = (value ?? '').toString();

    const token = String(tokenRaw)
      .replace(/^\[\[\s*/, '')
      .replace(/\s*\]\]$/, '')
      .trim();

    const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp(`\\[\\[\\s*${escaped}\\s*\\]\\]`, 'g');

    html = html.replace(re, val);
  };

  const repText = (tokenRaw, value) => {
    rep(tokenRaw, escapeHtml(t(value)));
  };

  const repMultilineText = (tokenRaw, value) => {
    rep(tokenRaw, formatPlainTextToEmailHtml(value));
  };

  const repAttr = (tokenRaw, value) => {
    rep(tokenRaw, escapeAttr(t(value)));
  };

  const repUrl = (tokenRaw, value) => {
    rep(tokenRaw, escapeAttr(t(value)));
  };

  const repNumber = (tokenRaw, value) => {
    const n = Number(value);
    rep(tokenRaw, Number.isFinite(n) ? String(n) : '');
  };

  // -----------------------------
  // Precomputed text blocks + spacers
  // -----------------------------
  const blogTextRaw = t(data.blog_text);
  const projectTextRaw = t(data.project_text);
  const collectionTextRaw = t(data.collection_text);
  const patternTextRaw = t(data.pattern_text);

  const magazineSpacer = getSpacerFromText(blogTextRaw, {
    targetLines: 16,
    lineHeightPx: 20,
    maxSpacer: 110,
    minSpacer: 8,
    charsPerLine: 42,
  });

  const projectSpacer = getSpacerFromText(projectTextRaw, {
    targetLines: 16,
    lineHeightPx: 20,
    maxSpacer: 120,
    minSpacer: 8,
    charsPerLine: 42,
  });


  // -----------------------------
  // 1) Global / fonts / logo / background structures
  // -----------------------------
  repText('[[EMAIL_TITLE]]', data.blog_title);

  repUrl('[[FONT_CASLONDORIC_URL]]', data.font_1);
  repUrl('[[FONT_ROMNARROW_URL]]', data.font_2);

  repUrl('[[STRUCTURE_BACKGROUND_IMAGE_1]]', full(data.structure_1));
  repUrl('[[STRUCTURE_BACKGROUND_IMAGE_2]]', full(data.structure_2));

  repUrl('[[LOGO_SRC]]', data.logo_src);
  repAttr('[[LOGO_ALT]]', t(data.logo_alt) || 'OAKCENT');

  // -----------------------------
  // 2) Magazine (blog) block
  // -----------------------------
  repUrl('[[HERO_IMAGE_1_SRC]]', full(data.heroImgBlog));
  repAttr('[[HERO_IMAGE_1_ALT]]', data.blog_title);

  repUrl('[[MAGAZINE_SIDE_IMAGE_1_SRC]]', full(data.sideImgBlog_1));
  repAttr('[[MAGAZINE_SIDE_IMAGE_1_ALT]]', data.blog_title);

  repUrl('[[MAGAZINE_SIDE_IMAGE_2_SRC]]', full(data.sideImgBlog_2));
  repAttr('[[MAGAZINE_SIDE_IMAGE_2_ALT]]', data.blog_title);

  repUrl('[[GALLERY_IMAGE_1_SRC]]', full(data.galleryImgBlog));
  repAttr('[[GALLERY_IMAGE_1_ALT]]', data.blog_title);

  repText('[[MAGAZINE_LABEL]]', 'Magazine');
  repText('[[MAGAZINE_TITLE]]', data.blog_title);
  repMultilineText('[[MAGAZINE_TEXT]]', blogTextRaw);

  repText('[[MAGAZINE_CTA_LABEL]]', data.blog_cta_label);
  repUrl('[[MAGAZINE_CTA_URL]]', t(data.blog_url) || full('/magazine/custom-production'));
  repNumber('[[MAGAZINE_CTA_SPACER]]', magazineSpacer);

  // -----------------------------
  // 3) Project block
  // -----------------------------
  repUrl('[[PROJECT_HERO_IMAGE_SRC]]', full(data.heroImgProject));
  repAttr('[[PROJECT_HERO_IMAGE_ALT]]', data.project_title);

  repUrl('[[PROJECT_IMAGE_1_SRC]]', full(data.firstBlock_img));
  repAttr('[[PROJECT_IMAGE_1_ALT]]', data.project_title);

  repUrl('[[PROJECT_IMAGE_2_SRC]]', full(data.secondBlock_img));
  repAttr('[[PROJECT_IMAGE_2_ALT]]', data.project_title);

  repText('[[PROJECT_TITLE]]', data.project_title);
  repMultilineText('[[PROJECT_TEXT]]', projectTextRaw);

  repText('[[PROJECT_CTA_LABEL]]', data.project_cta_label);
  repUrl('[[PROJECT_CTA_URL]]', t(data.project_url) || full('/projects'));
  repNumber('[[PROJECT_CTA_SPACER]]', projectSpacer);

  // -----------------------------
  // 4) Collection block
  // -----------------------------
  repText('[[COLLECTION_LABEL]]', 'Colour Collection');
  repText('[[COLLECTION_TITLE]]', data.collection_title);

  const collectionImageName = t(data.collection_name) || t(data.collection_title);
  const collectionSupabaseSrc = supabaseImg(supabaseCollectionBase, collectionImageName);
  const collectionImageSrcFinal = collectionSupabaseSrc || full(data.collection_image);

  repUrl('[[COLLECTION_IMAGE_SRC]]', collectionImageSrcFinal);
  repAttr('[[COLLECTION_IMAGE_ALT]]', data.collection_title);

  repMultilineText('[[COLLECTION_TEXT]]', collectionTextRaw);
  repText('[[COLLECTION_CTA_LABEL]]', data.collection_cta);

  const collectionUrl = t(data.collection_url) || '/floor-collection/sand';
  repUrl('[[COLLECTION_CTA_URL]]', full(collectionUrl));

  // -----------------------------
  // 5) Pattern block
  // -----------------------------
  repText('[[PATTERN_LABEL]]', 'Pattern Collection');
  repText('[[PATTERN_TITLE]]', data.pattern_title);

  const patternImageName = t(data.pattern_title);
  const patternSupabaseSrc = supabaseImg(supabasePatternBase, patternImageName);
  const patternImageSrcFinal = patternSupabaseSrc || full(data.pattern_img1);

  repUrl('[[PATTERN_IMAGE_SRC]]', patternImageSrcFinal);
  repAttr('[[PATTERN_IMAGE_ALT]]', patternImageName || t(data.pattern_title));

  repMultilineText('[[PATTERN_TEXT]]', patternTextRaw);
  repText('[[PATTERN_CTA_LABEL]]', data.pattern_cta);

  const patternUrl = t(data.patternCollection_url) || '/floor-collection/heritage';
  repUrl('[[PATTERN_CTA_URL]]', full(patternUrl));

  // -----------------------------
  // 6) CTA over forest background
  // -----------------------------
  repUrl('[[CTA_BACKGROUND_IMAGE]]', full(data.cta_background));
  repMultilineText('[[CTA_HEADLINE]]', data.cta_text);
  repText('[[CTA_BUTTON_LABEL]]', data.cta_button);

  const ctaButtonUrl = t(data.cta_button_url) || t(data.cta_url) || '#';
  repUrl('[[CTA_BUTTON_URL]]', ctaButtonUrl);

  // -----------------------------
  // 7) Socials
  // -----------------------------
  repUrl('[[SOCIAL_WEB_URL]]', t(data.soc_web_url) || '#');
  repUrl('[[SOCIAL_WEB_ICON_SRC]]', full(data.soc_web_src));
  repAttr('[[SOCIAL_WEB_ICON_ALT]]', t(data.soc_web_alt) || 'web');

  repUrl('[[SOCIAL_INSTAGRAM_URL]]', t(data.soc_ig_url) || '#');
  repUrl('[[SOCIAL_INSTAGRAM_ICON_SRC]]', full(data.soc_ig_src));
  repAttr('[[SOCIAL_INSTAGRAM_ICON_ALT]]', t(data.soc_ig_alt) || 'instagram');

  repUrl('[[SOCIAL_FACEBOOK_URL]]', t(data.soc_fb_url) || '#');
  repUrl('[[SOCIAL_FACEBOOK_ICON_SRC]]', full(data.soc_fb_src));
  repAttr('[[SOCIAL_FACEBOOK_ICON_ALT]]', t(data.soc_fb_alt) || 'facebook');

  repUrl('[[SOCIAL_PINTEREST_URL]]', t(data.soc_pin_url) || '#');
  repUrl('[[SOCIAL_PINTEREST_ICON_SRC]]', full(data.soc_pin_src));
  repAttr('[[SOCIAL_PINTEREST_ICON_ALT]]', t(data.soc_pin_alt) || 'pinterest');

  repUrl('[[SOCIAL_YOUTUBE_URL]]', t(data.soc_yt_url) || '#');
  repUrl('[[SOCIAL_YOUTUBE_ICON_SRC]]', full(data.soc_yt_src));
  repAttr('[[SOCIAL_YOUTUBE_ICON_ALT]]', t(data.soc_yt_alt) || 'youtube');

  repUrl('[[SOCIAL_LINKEDIN_URL]]', t(data.soc_li_url) || '#');
  repUrl('[[SOCIAL_LINKEDIN_ICON_SRC]]', full(data.soc_li_src));
  repAttr('[[SOCIAL_LINKEDIN_ICON_ALT]]', t(data.soc_li_alt) || 'linkedin');

  // -----------------------------
  // 8) Footer
  // -----------------------------
  repMultilineText('[[FOOTER_UNSUBSCRIBE_TEXT_BEFORE_LINK]]', data.unsub_text);
  repText('[[FOOTER_UNSUBSCRIBE_LINK_LABEL]]', t(data.unsub_label) || 'odhlásit');

  repUrl('[[FOOTER_UNSUBSCRIBE_URL]]', t(data.unsub_url) || '#');
  repText('[[FOOTER_COPYRIGHT_TEXT]]', data.copyright);

  // -----------------------------
  // Debug leftovers
  // -----------------------------
  const leftovers = html.match(/\[\[\s*[A-Z0-9_]+\s*\]\]/g) || [];

  return {
    json: {
      ...data,
      html_rendered: html,
      debug_leftover_tokens: leftovers,
      debug_spacers: {
        magazine: magazineSpacer,
        project: projectSpacer,
      },
    },
  };
});

// n8n Function node
// Expects your big JSON object (with html_template, blog_*, project_*, etc.) on item.json
// Outputs the same JSON + html_rendered (final email HTML)

return items.map(item => {
  const data = item.json;

  const base = (data.image_base_url || '').replace(/\/$/, '');

  const t = (v) => (typeof v === 'string' ? v.trim() : (v ?? ''));
  const full = (v) => {
    const s = t(v);
    if (!s) return '';
    if (/^https?:\/\//i.test(s)) return s; // already absolute
    return base + s;
  };

  // NEW: Supabase bases for collection & pattern images
  const supabaseCollectionBase = 'https://izohjxqvhacjmutgnckf.supabase.co/storage/v1/object/public/Newsletter/collection_images/';
  const supabasePatternBase   = 'https://izohjxqvhacjmutgnckf.supabase.co/storage/v1/object/public/Newsletter/pattern_images/';

  // Helper: build Supabase image URL from name, if provided
  const supabaseImg = (baseUrl, nameRaw) => {
    const name = t(nameRaw);
    if (!name) return '';
    // We assume filenames are exactly "<name>.png"
    return `${baseUrl}${name}.png`;
  };

  let html = t(data.html_template);
  if (!html) {
    throw new Error('html_template is missing on item.json');
  }

  // ✅ UPDATED: whitespace-tolerant replacement for [[TOKEN]]
  // Works with: [[TOKEN]], [[ TOKEN ]],  [[TOKEN]], url(' [[TOKEN]]'), href=" [[TOKEN]]"
  const rep = (tokenRaw, value) => {
    const val = (value ?? '').toString();

    // Accept calls like rep('[[EMAIL_TITLE]]', ...) OR rep('EMAIL_TITLE', ...)
    const token = String(tokenRaw)
      .replace(/^\[\[\s*/, '')
      .replace(/\s*\]\]$/, '')
      .trim();

    // Escape token for RegExp
    const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // Match [[TOKEN]] with any whitespace around TOKEN
    const re = new RegExp(`\\[\\[\\s*${escaped}\\s*\\]\\]`, 'g');

    html = html.replace(re, val);
  };

  //
  // 1) Global / fonts / logo / background structures
  //
  rep('[[EMAIL_TITLE]]', t(data.blog_title));

  rep('[[FONT_CASLONDORIC_URL]]', t(data.font_1));
  rep('[[FONT_ROMNARROW_URL]]', t(data.font_2));

  rep('[[STRUCTURE_BACKGROUND_IMAGE_1]]', full(data.structure_1));
  rep('[[STRUCTURE_BACKGROUND_IMAGE_2]]', full(data.structure_2));

  rep('[[LOGO_SRC]]', t(data.logo_src));
  rep('[[LOGO_ALT]]', t(data.logo_alt) || 'OAKCENT');

  //
  // 2) Magazine (blog) block
  //
  rep('[[HERO_IMAGE_1_SRC]]', full(data.heroImgBlog));
  rep('[[HERO_IMAGE_1_ALT]]', t(data.blog_title));

  rep('[[MAGAZINE_SIDE_IMAGE_1_SRC]]', full(data.sideImgBlog_1));
  rep('[[MAGAZINE_SIDE_IMAGE_1_ALT]]', t(data.blog_title));

  rep('[[MAGAZINE_SIDE_IMAGE_2_SRC]]', full(data.sideImgBlog_2));
  rep('[[MAGAZINE_SIDE_IMAGE_2_ALT]]', t(data.blog_title));

  rep('[[GALLERY_IMAGE_1_SRC]]', full(data.galleryImgBlog));
  rep('[[GALLERY_IMAGE_1_ALT]]', t(data.blog_title));

  rep('[[MAGAZINE_LABEL]]', 'Magazine');
  rep('[[MAGAZINE_TITLE]]', t(data.blog_title));

  const blogText =
    t(data.blog_text) ||
    [data.blog_p1, data.blog_p2, data.blog_p3, data.blog_p4, data.blog_p5, data.blog_p6]
      .map(t)
      .filter(Boolean)
      .join(' ');

  rep('[[MAGAZINE_TEXT]]', blogText);

  rep('[[MAGAZINE_PARAGRAPH_1]]', '');
  rep('[[MAGAZINE_PARAGRAPH_2]]', '');
  rep('[[MAGAZINE_PARAGRAPH_3]]', '');
  rep('[[MAGAZINE_PARAGRAPH_4]]', '');
  rep('[[MAGAZINE_PARAGRAPH_5]]', '');
  rep('[[MAGAZINE_PARAGRAPH_6]]', '');

  rep('[[MAGAZINE_CTA_LABEL]]', t(data.blog_cta_label));

  const blogUrl = t(data.blog_url) || full('/magazine/custom-production');
  rep('[[MAGAZINE_CTA_URL]]', blogUrl);

  //
  // 3) Project block
  //
  rep('[[PROJECT_HERO_IMAGE_SRC]]', full(data.heroImgProject));
  rep('[[PROJECT_HERO_IMAGE_ALT]]', t(data.project_title));

  rep('[[PROJECT_IMAGE_1_SRC]]', full(data.firstBlock_img));
  rep('[[PROJECT_IMAGE_1_ALT]]', t(data.project_title));

  rep('[[PROJECT_IMAGE_2_SRC]]', full(data.secondBlock_img));
  rep('[[PROJECT_IMAGE_2_ALT]]', t(data.project_title));

  rep('[[PROJECT_TITLE]]', t(data.project_title));

  const projectText =
    t(data.project_text) ||
    [data.project_p1, data.project_p2, data.project_p3, data.project_p4, data.project_p5]
      .map(t)
      .filter(Boolean)
      .join(' ');

  rep('[[PROJECT_TEXT]]', projectText);

  rep('[[PROJECT_PARAGRAPH_1]]', '');
  rep('[[PROJECT_PARAGRAPH_2]]', '');
  rep('[[PROJECT_PARAGRAPH_3]]', '');
  rep('[[PROJECT_PARAGRAPH_4]]', '');
  rep('[[PROJECT_PARAGRAPH_5]]', '');

  rep('[[PROJECT_CTA_LABEL]]', t(data.project_cta_label));

  const projectUrl = t(data.project_url) || full('/projects');
  rep('[[PROJECT_CTA_URL]]', projectUrl);

  //
  // 4) Collection block
  //
  rep('[[COLLECTION_LABEL]]', 'Colour Collection');
  rep('[[COLLECTION_TITLE]]', t(data.collection_title));

  const collectionImageName = data.collection_name || data.collection_title;
  const collectionSupabaseSrc = supabaseImg(supabaseCollectionBase, collectionImageName);
  const collectionImageSrcFinal = collectionSupabaseSrc || full(data.collection_image);

  rep('[[COLLECTION_IMAGE_SRC]]', collectionImageSrcFinal);
  rep('[[COLLECTION_IMAGE_ALT]]', t(data.collection_title));

const collectionText =
  t(data.collection_text) ||
  t(data.collection_body) ||     
  [data.collection_paragraph_1, data.collection_paragraph_2, data.collection_paragraph_3]
    .map(t)
    .filter(Boolean)
    .join(' ');

rep('[[COLLECTION_TEXT]]', collectionText);

rep('[[COLLECTION_CTA_LABEL]]', t(data.collection_cta));

const collectionUrl = t(data.collection_url) || '/floor-collection/sand';
rep('[[COLLECTION_CTA_URL]]', full(collectionUrl));

  //
  // 5) Pattern block
  //
rep('[[PATTERN_LABEL]]', 'Pattern Collection');
rep('[[PATTERN_TITLE]]', t(data.pattern_title));


const patternImageName = t(data.pattern_title);
const patternSupabaseSrc = supabaseImg(supabasePatternBase, patternImageName);
const patternImageSrcFinal = patternSupabaseSrc || full(data.pattern_img1);

rep('[[PATTERN_IMAGE_SRC]]', patternImageSrcFinal);
rep('[[PATTERN_IMAGE_ALT]]', patternImageName || t(data.pattern_title));

// ✅ text z DB
const patternText =
  t(data.pattern_text) ||
  t(data.pattern_body) ||
  [data.pattern_paragraph_1, data.pattern_paragraph_2]
    .map(t)
    .filter(Boolean)
    .join(' ');

rep('[[PATTERN_TEXT]]', patternText);

rep('[[PATTERN_CTA_LABEL]]', t(data.pattern_cta));

// ✅ URL z DB
const patternUrl =
  t(data.patternCollection_url) ||
  t(data.pattern_collectionUrl) ||
  '/floor-collection/heritage';

rep('[[PATTERN_CTA_URL]]', full(patternUrl));

  //
  // 6) CTA over forest background
  //
  rep('[[CTA_BACKGROUND_IMAGE]]', full(data.cta_background));
  rep('[[CTA_HEADLINE]]', t(data.cta_text));
  rep('[[CTA_BUTTON_LABEL]]', t(data.cta_button));

  const ctaButtonUrl =
    t(data.cta_button_url) ||
    t(data.cta_url) ||
    '#';

  rep('[[CTA_BUTTON_URL]]', ctaButtonUrl);

  //
  // 7) Socials
  //
  rep('[[SOCIAL_WEB_URL]]', t(data.soc_web_url) || '#');
  rep('[[SOCIAL_WEB_ICON_SRC]]', full(data.soc_web_src));
  rep('[[SOCIAL_WEB_ICON_ALT]]', t(data.soc_web_alt) || 'web');

  rep('[[SOCIAL_INSTAGRAM_URL]]', t(data.soc_ig_url) || '#');
  rep('[[SOCIAL_INSTAGRAM_ICON_SRC]]', full(data.soc_ig_src));
  rep('[[SOCIAL_INSTAGRAM_ICON_ALT]]', t(data.soc_ig_alt) || 'instagram');

  rep('[[SOCIAL_FACEBOOK_URL]]', t(data.soc_fb_url) || '#');
  rep('[[SOCIAL_FACEBOOK_ICON_SRC]]', full(data.soc_fb_src));
  rep('[[SOCIAL_FACEBOOK_ICON_ALT]]', t(data.soc_fb_alt) || 'facebook');

  rep('[[SOCIAL_PINTEREST_URL]]', t(data.soc_pin_url) || '#');
  rep('[[SOCIAL_PINTEREST_ICON_SRC]]', full(data.soc_pin_src));
  rep('[[SOCIAL_PINTEREST_ICON_ALT]]', t(data.soc_pin_alt) || 'pinterest');

  rep('[[SOCIAL_YOUTUBE_URL]]', t(data.soc_yt_url) || '#');
  rep('[[SOCIAL_YOUTUBE_ICON_SRC]]', full(data.soc_yt_src));
  rep('[[SOCIAL_YOUTUBE_ICON_ALT]]', t(data.soc_yt_alt) || 'youtube');

  rep('[[SOCIAL_LINKEDIN_URL]]', t(data.soc_li_url) || '#');
  rep('[[SOCIAL_LINKEDIN_ICON_SRC]]', full(data.soc_li_src));
  rep('[[SOCIAL_LINKEDIN_ICON_ALT]]', t(data.soc_li_alt) || 'linkedin');

  //
  // 8) Footer
  //
  rep('[[FOOTER_UNSUBSCRIBE_TEXT_BEFORE_LINK]]', t(data.unsub_text));
  rep('[[FOOTER_UNSUBSCRIBE_LINK_LABEL]]', t(data.unsub_label) || 'odhlásit');

  const unsubUrl = t(data.unsub_url) || '#';
  rep('[[FOOTER_UNSUBSCRIBE_URL]]', unsubUrl);

  rep('[[FOOTER_COPYRIGHT_TEXT]]', t(data.copyright));

  // Optional debug: see what tokens are still not replaced
  const leftovers = (html.match(/\[\[\s*[A-Z0-9_]+\s*\]\]/g) || []);

  return {
    json: {
      ...data,
      html_rendered: html,
      debug_leftover_tokens: leftovers,
    },
  };
});
